Layout.Stylesheet:
body { margin: 0; font-size: 9pt; }
div { margin: 5pt; padding: 10pt; border: 2pt solid blue; background-color: lightblue; }
.r5 { border-radius: 5pt; }
.r10 { border-radius: 10pt; }
.r20 { border-radius: 20pt; }
.corners { border-top-left-radius: 5pt; border-top-right-radius: 10pt; border-bottom-right-radius: 15pt; border-bottom-left-radius: 20pt; }
